service-call.in-map:
{operationKey:operationKey, shipmentId:shipmentId, productId:productId,
                        assemblyProductId:assemblyProductId || null, quantity:quantity,
                        shipmentPackageSeqId:shipmentPackageSeqId || null}

actions.message:
Package ${edited.result.shipmentPackageSeqId || ''}
                ${({CREATED: 'added', UPDATED: 'saved', WEIGHED: 'weighed', DELETED: 'removed',
                    MOVED: 'contents moved'})[edited.result.resultCode] || ''}

Package ${reopened.result.shipmentPackageSeqId} is open again
                ${reopened.result.releasedInvoiceIds.length ? '; invoice ' + reopened.result.releasedInvoiceIds.join(', ') +
                    ' released' : ''}
